export type StatIdNames = keyof (typeof StatIdByName)

const statIdByLowerName: Record<string, StatId> = {};
for (const [k, v] of Object.entries(StatIdByName)) {
  statIdByLowerName[k.toLowerCase()] = v;
}

// parseStatId resolves a member by name, case-insensitively, mirroring the Go
// Parse method. Returns undefined when the name is unknown.
export function parseStatId(name: string): StatId | undefined {
  return statIdByLowerName[name.trim().toLowerCase()];
}
